WITH filtered_accounts AS (SELECT *, LOWER(status) AS status_lower FROM accounts WHERE account_type <> 'CHECKING'), account_type_summary AS (SELECT account_type, ROUND(STDDEV(balance), 2) AS stddev_balance, MAX(opened_date) AS last_opened_date FROM filtered_accounts GROUP BY account_type) SELECT account_type, stddev_balance, last_opened_date FROM account_type_summary ORDER BY stddev_balance DESC
